const draft = new Promise((resolve) => resolve("draft"));

draft
  .then((doc) => {
    throw new TypeError("cannot publish " + doc);
  })
  .catch((error) => {
    if (error instanceof RangeError) {
      return "fixed";
    }
    throw error;
  })
  .then(
    (doc) => console.log("published " + doc),
    (error) => {
      console.log(error.name);
      return error;
    }
  )
  .finally(() => console.log("closed"))
  .then((value) => console.log(value.message));
